const parseDryRun = (v) => v === true || v === 'true' || v === 1 || v === '1';

let body = $json.body ?? $json;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}
if (!body || typeof body !== 'object') body = {};

const keywordsInput = body.keywords;
const daysInput = body.days;
const dryRunRaw = body.dryRun ?? $json.dryRun ?? $json.query?.dryRun;
const dryRun = parseDryRun(dryRunRaw);

const makeRunId = () => {
  const runIdRaw = body.runId ?? $json.runId ?? $json.query?.runId;
  const provided = typeof runIdRaw === 'string' ? runIdRaw.trim() : '';
  if (provided) return provided.slice(0, 64);

  try {
    if (globalThis?.crypto?.randomUUID) {
      return globalThis.crypto.randomUUID();
    }
  } catch {
    // fallback below
  }

  try {
    const { randomUUID } = require('crypto');
    return randomUUID();
  } catch {
    return `run-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  }
};

const runId = makeRunId();
const fallbackKeywords = ['Gen Z travel', '혼자여행'];
const keywords = (Array.isArray(keywordsInput) ? keywordsInput : fallbackKeywords)
  .map((k) => (typeof k === 'string' ? k.trim() : ''))
  .filter((k) => k.length > 0)
  .slice(0, 30);

if (!keywords.length) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_KEYWORDS',
      message: 'keywords must be a non-empty array of strings',
      keywords: [],
      days: Number.isFinite(Number(daysInput)) ? Math.max(1, Math.trunc(Number(daysInput))) : 30,
      dryRun,
      runId,
      startedAtISO: new Date().toISOString()
    }
  }];
}

const daysNumber = Number(daysInput);
if (!Number.isFinite(daysNumber) || Math.trunc(daysNumber) < 1) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_DAYS',
      message: 'days must be a positive integer',
      keywords,
      days: 30,
      dryRun,
      runId,
      startedAtISO: new Date().toISOString()
    }
  }];
}

const days = Math.min(90, Math.trunc(daysNumber));

return [{
  json: {
    ok: true,
    keywords,
    days,
    dryRun,
    runId,
    startedAtISO: new Date().toISOString()
  }
}];

const req = $('Parse_Request').first().json || {};
return [{
  json: {
    dryRun: req.dryRun === true,
    headerMatrix: [[
      'collectedAtISO','collectedDateKST','createTimeISO','createDateKST','bucket','keyword','query','proxyCountryCode','id','text','textLanguage','videoUrl','authorName','authorNickName','authorProfileUrl','authorFollowers','playCount','diggCount','shareCount','commentCount','inLookback','runId'
    ]]
  }
}];

const req = $('Parse_Request').first().json || {};

const getEnvString = (key, fallback = '') => {
  const val = $env[key];
  if (val === undefined || val === null || val === '') return fallback;
  return String(val).trim();
};

const getEnvInt = (key, fallback) => {
  const raw = $env[key];
  const num = Number.parseInt(raw ?? '', 10);
  return Number.isFinite(num) ? num : fallback;
};

if (req.ok === false) {
  return [{
    json: {
      skipWorkflow: true,
      dryRun: Boolean(req.dryRun),
      runId: req.runId || null,
      startedAtISO: req.startedAtISO || new Date().toISOString(),
      fatalErrorCode: req.reason || 'INVALID_REQUEST',
      fatalErrorMessage: req.message || 'Invalid request payload',
      jobsTotal: 0,
      jobsSucceeded: 0,
      jobsFailed: 1,
      sheetsRangesWouldWrite: {
        ensureHeader: `${getEnvString('GSHEET_RAW_TAB', 'raw_events')}!A1:V1`,
        appendRows: `${getEnvString('GSHEET_RAW_TAB', 'raw_events')}!A:V`
      }
    }
  }];
}

const { keywords, days, startedAtISO, dryRun, runId } = req;
const actorRaw = getEnvString('APIFY_ACTOR');
const token = getEnvString('APIFY_TOKEN');

const jobsCount = keywords.length;
const maxItemsPerRun = Math.max(1, getEnvInt('MAX_ITEMS_PER_RUN', 2000));
const requestedPerJob = Math.max(1, getEnvInt('APIFY_RESULTS_PER_PAGE', 20));
const perJobCap = Math.max(1, Math.floor(maxItemsPerRun / Math.max(1, jobsCount)));
const resultsLimit = Math.max(1, Math.min(200, requestedPerJob, perJobCap));

const actorNormalized = (actorRaw || 'clockworks/tiktok-scraper').replace(/\//g, '~');
const waitForFinish = Math.max(1, getEnvInt('APIFY_WAIT_FOR_FINISH_SECS', 180));
const gsheetRawTab = getEnvString('GSHEET_RAW_TAB', 'raw_events');
const defaultBucket = getEnvString('COLLECT_BUCKET', 'GLOBAL');
const defaultProxyCountryCode = getEnvString('APIFY_PROXY_COUNTRY_CODE', 'KR');

const missing = [];
if (!actorRaw) missing.push('APIFY_ACTOR');
if (!token) missing.push('APIFY_TOKEN');

if (missing.length > 0) {
  return [{
    json: {
      skipWorkflow: true,
      dryRun,
      runId: runId || null,
      startedAtISO: startedAtISO || new Date().toISOString(),
      fatalErrorCode: 'MISSING_ENV',
      fatalErrorMessage: `Missing required environment variable(s): ${missing.join(', ')}. Set them in Southpole docker/.env.instance2 and ensure N8N_BLOCK_ENV_ACCESS_IN_NODE=false.`,
      missingEnvVars: missing,
      jobsTotal: jobsCount,
      jobsSucceeded: 0,
      jobsFailed: jobsCount,
      perJobCap,
      resultsLimit,
      sheetsRangesWouldWrite: {
        ensureHeader: `${gsheetRawTab}!A1:V1`,
        appendRows: `${gsheetRawTab}!A:V`
      }
    }
  }];
}

const jobs = keywords.map((keyword) => {
  const query = String(keyword || '').trim();
  const runUrlNoToken = `https://api.apify.com/v2/acts/${actorNormalized}/runs?waitForFinish=${waitForFinish}`;
  const datasetUrlTemplateNoToken = `https://api.apify.com/v2/datasets/{datasetId}/items?clean=true&format=json&limit=${resultsLimit}`;

  return {
    keyword: query,
    days,
    dryRun,
    runId,
    startedAtISO: startedAtISO || new Date().toISOString(),
    jobStartedAtISO: new Date().toISOString(),
    query,
    bucket: defaultBucket,
    proxyCountryCode: defaultProxyCountryCode,
    actorRaw,
    actorNormalized,
    skipWorkflow: false,
    jobsCount,
    perJobCap,
    resultsLimit,
    waitForFinish,
    apifyRunUrl: runUrlNoToken,
    apifyRunUrlNoToken: runUrlNoToken,
    apifyDatasetItemsUrlTemplate: datasetUrlTemplateNoToken,
    sheetsRangesWouldWrite: {
      ensureHeader: `${gsheetRawTab}!A1:V1`,
      appendRows: `${gsheetRawTab}!A:V`
    }
  };
});

return jobs.map((j) => ({ json: j }));

const job = $('Split_Jobs').item.json || {};

const errorOut = (stage, code, httpStatus, message, retriable, meta = {}) => {
  return [{
    json: {
      ...job,
      ok: false,
      stage,
      error: { code, httpStatus, message, retriable },
      rawItems: [],
      datasetId: null,
      defaultDatasetId: null,
      apifyRunId: meta.runId ?? null,
      apifyRunStatus: meta.status ?? null,
      apifyActorId: meta.actorId ?? (job.actorNormalized || null),
      waitedSeconds: meta.waitedSeconds ?? 0,
      fetchedCount: 0,
      fetchedAtISO: new Date().toISOString()
    }
  }];
};

const token = String($env.APIFY_TOKEN || '').trim();
const actorId = String(job.actorNormalized || '').trim();
if (!token) return errorOut('Run_Apify_TikTok', 'MISSING_APIFY_TOKEN', 400, 'APIFY_TOKEN is not configured', false);
if (!actorId) return errorOut('Run_Apify_TikTok', 'MISSING_APIFY_ACTOR', 400, 'APIFY_ACTOR is not configured', false);

const waitForFinish = Number.parseInt($env.APIFY_WAIT_FOR_FINISH_SECS || String(job.waitForFinish || 180), 10) || 180;
const timeoutSecs = Math.max(waitForFinish, Number.parseInt($env.APIFY_TIMEOUT_SECS || '', 10) || 300);
const runUrl = `https://api.apify.com/v2/acts/${actorId}/runs?waitForFinish=${waitForFinish}&token=${token}`;
const runUrlNoToken = `https://api.apify.com/v2/acts/${actorId}/runs?waitForFinish=${waitForFinish}`;
const runInfoBase = 'https://api.apify.com/v2/actor-runs';

const runInput = {
  searchQueries: [String(job.keyword || job.query || '').trim()],
  proxyCountryCode: job.proxyCountryCode,
  resultsPerPage: Number(job.resultsLimit || 20),
  searchSection: '/video'
};

const retriableByStatus = (status) => [408, 409, 425, 429, 500, 502, 503, 504].includes(status);
const terminalFailStatuses = new Set(['FAILED', 'ABORTED', 'TIMED-OUT', 'TIMED_OUT']);
const successStatus = 'SUCCEEDED';

const request = async (options) => {
  return await this.helpers.httpRequest({
    ...options,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
};

const startedMs = Date.now();
const elapsedSecs = () => Math.max(0, Math.floor((Date.now() - startedMs) / 1000));

let runRes;
try {
  runRes = await request({
    method: 'POST',
    url: runUrl,
    body: runInput,
    headers: { 'Content-Type': 'application/json' },
  });
} catch (err) {
  return errorOut('Run_Apify_TikTok', 'APIFY_RUN_NETWORK_ERROR', null, String(err.message || err), true, { actorId, waitedSeconds: elapsedSecs() });
}

const runStatusCode = Number(runRes?.statusCode || 0);
const runBody = runRes?.body || null;
if (runStatusCode < 200 || runStatusCode >= 300) {
  const msg = runBody?.error?.message || runBody?.message || `Apify run call failed (${runStatusCode || 'no status'})`;
  return errorOut('Run_Apify_TikTok', 'APIFY_RUN_FAILED', runStatusCode || null, msg, retriableByStatus(runStatusCode), { actorId, waitedSeconds: elapsedSecs() });
}

const runData = runBody?.data || {};
let datasetId = runData.defaultDatasetId || runData.datasetId || runBody?.defaultDatasetId || runBody?.datasetId || null;
const runId = runData.id || runBody?.id || null;
let runStatusText = String(runData.status || runBody?.status || '').toUpperCase() || null;

if (!runId) {
  return errorOut('Run_Apify_TikTok', 'MISSING_RUN_ID', 502, 'Apify run succeeded but runId was not returned', true, {
    actorId,
    status: runStatusText,
    waitedSeconds: elapsedSecs()
  });
}

let backoffA = 3;
let backoffB = 5;

const pollRun = async () => {
  const runInfoUrl = `${runInfoBase}/${runId}?token=${token}`;
  try {
    const infoRes = await request({ method: 'GET', url: runInfoUrl });
    const infoCode = Number(infoRes?.statusCode || 0);
    const infoBody = infoRes?.body || null;

    if (infoCode < 200 || infoCode >= 300) {
      const msg = infoBody?.error?.message || infoBody?.message || `Apify run status poll failed (${infoCode || 'no status'})`;
      return { ok: false, code: infoCode || null, message: msg, retriable: retriableByStatus(infoCode) };
    }

    const infoData = infoBody?.data || {};
    const status = String(infoData.status || infoBody?.status || '').toUpperCase() || null;
    const dsId = infoData.defaultDatasetId || infoData.datasetId || infoBody?.defaultDatasetId || infoBody?.datasetId || null;
    return { ok: true, status, datasetId: dsId };
  } catch (err) {
    return { ok: false, code: null, message: String(err.message || err), retriable: true };
  }
};

while (runStatusText !== successStatus) {
  const waitedSeconds = elapsedSecs();
  if (waitedSeconds >= timeoutSecs) {
    return errorOut(
      'Poll_Apify_Run_Status',
      'APIFY_RUN_TIMEOUT',
      408,
      `Apify run did not finish within timeout (status=${runStatusText || 'UNKNOWN'}, timeoutSecs=${timeoutSecs})`,
      true,
      { actorId, runId, status: runStatusText, waitedSeconds }
    );
  }

  if (runStatusText && terminalFailStatuses.has(runStatusText)) {
    return errorOut(
      'Poll_Apify_Run_Status',
      'APIFY_RUN_TERMINAL_FAILURE',
      409,
      `Apify run finished with terminal failure status=${runStatusText}`,
      false,
      { actorId, runId, status: runStatusText, waitedSeconds }
    );
  }

  const poll = await pollRun();
  if (!poll.ok) {
    return errorOut(
      'Poll_Apify_Run_Status',
      'APIFY_RUN_STATUS_POLL_FAILED',
      poll.code,
      poll.message,
      poll.retriable,
      { actorId, runId, status: runStatusText, waitedSeconds }
    );
  }

  runStatusText = poll.status || runStatusText;
  if (poll.datasetId) datasetId = poll.datasetId;

  if (runStatusText === successStatus) break;
  if (runStatusText && terminalFailStatuses.has(runStatusText)) {
    return errorOut(
      'Poll_Apify_Run_Status',
      'APIFY_RUN_TERMINAL_FAILURE',
      409,
      `Apify run finished with terminal failure status=${runStatusText}`,
      false,
      { actorId, runId, status: runStatusText, waitedSeconds: elapsedSecs() }
    );
  }

  const delaySecs = Math.min(20, backoffA);
  await new Promise((resolve) => setTimeout(resolve, delaySecs * 1000));
  const next = backoffA + backoffB;
  backoffA = backoffB;
  backoffB = next;
}

const waitedSeconds = elapsedSecs();

if (!datasetId) {
  const poll = await pollRun();
  if (poll.ok && poll.datasetId) datasetId = poll.datasetId;
}

if (!datasetId) {
  return errorOut('Run_Apify_TikTok', 'MISSING_DATASET_ID', 502, 'Apify run succeeded but datasetId was not found', true, {
    actorId,
    runId,
    status: runStatusText,
    waitedSeconds
  });
}

const limit = Number(job.resultsLimit || 20);
const datasetItemsUrlNoToken = `https://api.apify.com/v2/datasets/${datasetId}/items?clean=true&format=json&limit=${limit}`;
const datasetItemsUrl = `${datasetItemsUrlNoToken}&token=${token}`;

const maxRetries = 5;
let attempt = 0;
let itemsCode = 0;
let itemsBody = null;

while (attempt < maxRetries) {
  attempt += 1;
  try {
    const itemsRes = await request({ method: 'GET', url: datasetItemsUrl });
    itemsCode = Number(itemsRes?.statusCode || 0);
    itemsBody = itemsRes?.body ?? null;

    if (itemsCode !== 429) break;
    if (attempt >= maxRetries) {
      return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_RATE_LIMIT', itemsCode || null, 'Dataset items endpoint rate-limited after retries', true, {
        actorId,
        runId,
        status: runStatusText,
        waitedSeconds
      });
    }

    const backoffMs = 1000 * (2 ** (attempt - 1));
    await new Promise((resolve) => setTimeout(resolve, backoffMs));
  } catch (err) {
    if (attempt >= maxRetries) {
      return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_NETWORK_ERROR', null, String(err.message || err), true, {
        actorId,
        runId,
        status: runStatusText,
        waitedSeconds
      });
    }
    const backoffMs = 1000 * (2 ** (attempt - 1));
    await new Promise((resolve) => setTimeout(resolve, backoffMs));
  }
}

if (itemsCode < 200 || itemsCode >= 300) {
  const msg = itemsBody?.error?.message || itemsBody?.message || `Dataset items fetch failed (${itemsCode || 'no status'})`;
  return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_FETCH_FAILED', itemsCode || null, msg, retriableByStatus(itemsCode), {
    actorId,
    runId,
    status: runStatusText,
    waitedSeconds
  });
}

const rawItems = Array.isArray(itemsBody)
  ? itemsBody
  : Array.isArray(itemsBody?.data)
    ? itemsBody.data
    : [];

return [{
  json: {
    ...job,
    ok: true,
    stage: 'Fetch_Dataset_Items',
    error: null,
    datasetId,
    defaultDatasetId: datasetId,
    apifyRunId: runId,
    apifyRunStatus: runStatusText || successStatus,
    apifyActorId: actorId,
    waitedSeconds,
    apifyRunUrl: runUrlNoToken,
    datasetItemsUrl: datasetItemsUrlNoToken,
    rawItems,
    fetchedCount: rawItems.length,
    sampleRawItemTop1: rawItems.length ? rawItems[0] : null,
    fetchedAtISO: new Date().toISOString()
  }
}];

const started = Date.now();
try {
  const payload = $json || {};
  const job = $('Split_Jobs').item.json || {};

  if (payload.ok === false || payload.error) {
    const nowIso = new Date().toISOString();
    return [{
      json: {
        ...job,
        ok: false,
        stage: payload.stage || 'Run_Apify_TikTok',
        error: payload.error || null,
        fetchedCount: Number(payload.fetchedCount || 0),
        inLookbackCount: 0,
        appendCountPlanned: 0,
        rowsMatrix: [],
        sampleRawItemTop1: payload.sampleRawItemTop1 ?? null,
        top5MappedRows: { columns: [], rows: [] },
        apifyActorId: payload.apifyActorId || job.actorNormalized || null,
        apifyRunId: payload.apifyRunId || null,
        apifyRunStatus: payload.apifyRunStatus || null,
        datasetId: payload.datasetId || payload.defaultDatasetId || null,
        defaultDatasetId: payload.defaultDatasetId || payload.datasetId || null,
        waitedSeconds: Number(payload.waitedSeconds || job.waitForFinish || 0) || null,
        startedAtISO: job.jobStartedAtISO || job.startedAtISO || nowIso,
        finishedAtISO: nowIso,
        durationMs: Math.max(0, Date.now() - new Date(job.jobStartedAtISO || job.startedAtISO || nowIso).getTime()),
        errorMessage: payload.error?.message || 'Apify execution failed'
      }
    }];
  }

  const rawItems = Array.isArray(payload.rawItems) ? payload.rawItems : [];

  const toNumOrNull = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const toIso = (v) => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v === 'number') {
      const ms = v > 1e12 ? v : v > 1e9 ? v * 1000 : null;
      if (!ms) return null;
      const d = new Date(ms);
      return Number.isNaN(d.getTime()) ? null : d.toISOString();
    }
    const d = new Date(v);
    return Number.isNaN(d.getTime()) ? null : d.toISOString();
  };

  const toKstDate = (iso) => {
    if (!iso) return null;
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return null;
    return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });
  };

  const nowIso = new Date().toISOString();
  const todayKst = toKstDate(nowIso);
  const startDate = new Date(Date.now() - (Math.max(1, Number(job.days || 30)) - 1) * 86400000);
  const startKst = startDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });

  const mappedRows = rawItems.map((item) => {
    const createTimeISO = toIso(item.createTimeISO ?? item.createTime ?? item.createdAt ?? null);
    const createDateKST = toKstDate(createTimeISO);
    const inLookback = Boolean(createDateKST && createDateKST >= startKst && createDateKST <= todayKst);
    const author = item.authorMeta || {};

    return {
      collectedAtISO: nowIso,
      collectedDateKST: todayKst,
      createTimeISO,
      createDateKST,
      bucket: job.bucket,
      keyword: job.keyword,
      query: job.query,
      proxyCountryCode: job.proxyCountryCode,
      id: item.id ?? null,
      text: item.text ?? null,
      textLanguage: item.textLanguage ?? null,
      videoUrl: item.webVideoUrl ?? item.videoUrl ?? null,
      authorName: author.name ?? null,
      authorNickName: author.nickName ?? null,
      authorProfileUrl: author.profileUrl ?? null,
      authorFollowers: toNumOrNull(author.fans),
      playCount: toNumOrNull(item.playCount),
      diggCount: toNumOrNull(item.diggCount),
      shareCount: toNumOrNull(item.shareCount),
      commentCount: toNumOrNull(item.commentCount),
      inLookback,
      runId: job.runId || null
    };
  });

  const rowsMatrix = mappedRows.map((r) => ([
    r.collectedAtISO,
    r.collectedDateKST,
    r.createTimeISO,
    r.createDateKST,
    r.bucket,
    r.keyword,
    r.query,
    r.proxyCountryCode,
    r.id,
    r.text,
    r.textLanguage,
    r.videoUrl,
    r.authorName,
    r.authorNickName,
    r.authorProfileUrl,
    r.authorFollowers,
    r.playCount,
    r.diggCount,
    r.shareCount,
    r.commentCount,
    r.inLookback,
    r.runId
  ]));

  const previewColumns = [
    'collectedAtISO','collectedDateKST','createTimeISO','createDateKST','bucket','keyword','query','proxyCountryCode','id','text','textLanguage','videoUrl','authorName','authorNickName','authorProfileUrl','authorFollowers','playCount','diggCount','shareCount','commentCount','inLookback','runId'
  ];

  const finishedAtISO = new Date().toISOString();
  const durationMs = Date.now() - (new Date(job.jobStartedAtISO || job.startedAtISO || finishedAtISO).getTime() || Date.now());

  return [{
    json: {
      ...job,
      ok: true,
      actorUsed: job.actorNormalized,
      requestedDays: Number(job.days || 30),
      fetchedCount: mappedRows.length,
      inLookbackCount: mappedRows.filter((r) => r.inLookback).length,
      appendCountPlanned: mappedRows.length,
      rowsMatrix,
      datasetId: payload.datasetId || payload.defaultDatasetId || null,
      defaultDatasetId: payload.defaultDatasetId || payload.datasetId || null,
      apifyRunId: payload.apifyRunId || null,
      apifyRunStatus: payload.apifyRunStatus || null,
      apifyActorId: payload.apifyActorId || job.actorNormalized || null,
      waitedSeconds: Number(payload.waitedSeconds || job.waitForFinish || 0) || null,
      apifyRunUrl: job.apifyRunUrl,
      apifyDatasetItemsUrl: payload.datasetItemsUrl || null,
      sampleRawItemTop1: rawItems.length > 0 ? rawItems[0] : null,
      top5MappedRows: {
        columns: previewColumns,
        rows: mappedRows.slice(0, 5)
      },
      startedAtISO: job.jobStartedAtISO || job.startedAtISO || nowIso,
      finishedAtISO,
      durationMs,
      errorMessage: null
    }
  }];
} catch (err) {
  return [{
    json: {
      ok: false,
      fetchedCount: 0,
      inLookbackCount: 0,
      appendCountPlanned: 0,
      rowsMatrix: [],
      sampleRawItemTop1: null,
      top5MappedRows: { columns: [], rows: [] },
      errorMessage: `MAPPING_ERROR: ${err.message}`,
      durationMs: Date.now() - started
    }
  }];
}

const current = $json || {};
let planned;
try {
  planned = $('Map_To_RawEvents_Schema').item.json || {};
} catch {
  planned = current;
}

const appendError = current.error?.message ? String(current.error.message) : null;
const isDryRun = planned.dryRun === true;
const isSkip = planned.skipWorkflow === true;
const nowIso = new Date().toISOString();
const startTs = new Date(planned.jobStartedAtISO || planned.startedAtISO || nowIso).getTime();

const sanitizeError = (err) => {
  if (!err) return null;
  if (typeof err === 'string') return { message: err };
  return {
    code: err.code ?? null,
    httpStatus: err.httpStatus ?? null,
    message: err.message ? String(err.message) : String(err),
    retriable: err.retriable ?? null
  };
};

const errObj = sanitizeError(planned.error);
const errorMessage = planned.fatalErrorMessage || planned.errorMessage || appendError || errObj?.message || null;

return [{
  json: {
    dryRun: isDryRun,
    runId: planned.runId || null,
    bucket: planned.bucket || null,
    keyword: planned.keyword || null,
    query: planned.query || null,
    proxyCountryCode: planned.proxyCountryCode || null,
    actorUsed: planned.actorUsed || planned.actorNormalized || planned.apifyActorId || null,
    apifyActorId: planned.apifyActorId || planned.actorNormalized || null,
    apifyRunId: planned.apifyRunId || null,
    datasetId: planned.datasetId || planned.defaultDatasetId || null,
    defaultDatasetId: planned.defaultDatasetId || planned.datasetId || null,
    apifyRunStatus: planned.apifyRunStatus || null,
    waitedSeconds: Number(planned.waitedSeconds || 0) || null,
    requestedDays: planned.requestedDays || planned.days || null,
    jobsCount: planned.jobsCount || null,
    perJobCap: planned.perJobCap || null,
    resultsLimit: planned.resultsLimit || null,
    apifyRunUrl: planned.apifyRunUrl || null,
    apifyDatasetItemsUrlTemplate: planned.apifyDatasetItemsUrlTemplate || null,
